shots.draw_js:
clearScene();setBig(null);setEq(null);
note("病因：数据来自专家的分布",640,280,"r lg");
note("而你走在自己的分布上",640,350,"r lg");
setCap("诊断已经很清楚了。<b>那修法应该冲着哪一项去？</b>");

clearScene();setEq(null);
setBig("多收集点专家数据","数据越多，覆盖越全");
setCap("再多也没用：<b>专家的数据永远只覆盖专家的分布</b>。");

clearScene();setBig(null);setEq(null);
note("① 用当前策略跑",360,250,"b lg","start");
note("② 在这些状态上问专家",360,330,"g lg","start");
note("③ 加进数据集，重训",360,410,"y lg","start");
setCap("<b>DAgger</b>：让专家标注<b>你自己会到达的</b>那些状态。");

clearScene();setBig(null);setEq(null);
fillBars({order:[0,1],step:760,vals:[4.65,0.30],
  x:380,y:430,w:520,h:170,max:5.1,
  label:function(i){return ["行为克隆 εT(T+1)/2","DAgger O(εT)"][i];},
  cls:function(i){return i===0?"r":"g";},
  fmt:function(v){return v.toFixed(2);}});
note("ε=0.01, T=30",640,466,"y");
setCap("同样的 ε 与 T：界从 <b>4.65</b> 降到 <b>0.30</b>，而且<b>阶</b>从 T² 变回 T。");

clearScene();setBig(null);setEq(null);
lamps({y:280,gap:330,items:[
  {label:"要的不是更多",sub:"是不同分布的数据",state:"on"},
  {label:"代价",sub:"专家必须能被反复询问",state:"dead"},
  {label:"且要标怪状态",sub:"人类在这上面很不可靠",state:"dead"}]});
note("这一条最难满足",640,420,"r");
setCap("<b>指名反驳</b>：要的不是更多数据，是<b>不同分布</b>的数据。");

clearScene();setBig(null);
setEq("$$R(s)=w^{\\top}x(s) \\qquad \\mu(\\pi)=\\sum_t \\gamma^t x(s_t)$$","top");
note("值就变成 wᵀμ",640,300,"g lg");
note("于是可以只比 μ",640,360,"y lg");
setCap("若奖励对特征<b>线性</b>，策略的值就写成 <b>wᵀμ(π)</b> —— 只剩一个向量要比。");

clearScene();setEq(null);
setBig("匹配 μ 就等于策略相同","特征一样，行为当然一样");
setCap("匹配 μ 只保证<b>线性奖励下的值</b>接近 —— 不保证策略相同。");

clearScene();setBig(null);setEq(null);
note("μ 的维数 = 特征数 k",360,270,"y lg","start");
note("不是状态数",360,340,"r lg","start");
note("也没有 (1−γ) 归一化",360,410,"r lg","start");
setCap("两处记号必须更正：μ <b>按特征编号</b>，而且它<b>不是概率分布</b>。");

clearScene();setBig(null);
setEq("$$|w^{\\top}\\mu(\\pi)-w^{\\top}\\mu_E| \\le \\lVert w\\rVert\\,\\lVert \\mu(\\pi)-\\mu_E\\rVert$$","top");
note("配对必须一致",640,300,"r lg");
note("原文用 L2 / L2",640,360,"g lg");
setCap("两个值的差被<b>范数乘积</b>控住 —— 但两个范数必须<b>配成一对</b>。");

clearScene();setBig(null);setEq(null);
lamps({y:280,gap:330,items:[
  {label:"μ 匹配",sub:"线性奖励下值接近",state:"on"},
  {label:"策略相同",sub:"不保证",state:"dead"},
  {label:"除非",sub:"x 是 one-hot",state:"on"}]});
note("保证的是值，不是行为",640,420,"y");
setCap("<b>指名反驳</b>：μ 匹配保证的是<b>值</b>接近，不是<b>行为</b>相同。");

clearScene();setBig(null);setEq(null);
note("看见最优行为",400,280,"g lg");
note("反推奖励",880,280,"y lg");
note("这个反问题有解吗",640,400,"r lg");
setCap("逆强化学习问的是一个<b>反问题</b>：什么样的 R 让专家的行为最优？");

clearScene();setEq(null);
setBig("专家最优，R 就定了","行为已经把偏好全暴露了");
setCap("行为确实暴露了偏好 —— <b>但暴露得远远不够定出一个 R</b>。");

clearScene();setBig(null);
setEq("$$R\\equiv 0 \\;\\Longrightarrow\\; \\text{every policy is optimal}$$","top");
note("包括专家那个",640,300,"r lg");
note("所以它是一个合法解",640,360,"r lg");
setCap("取 <b>R ≡ 0</b>：所有策略的值都是 0，<b>每一个</b>策略都是最优的。");

clearScene();setBig(null);setEq(null);
note("特征匹配",360,260,"g lg","start");
note("最大间隔",360,335,"b lg","start");
note("最大熵",360,410,"v lg","start");
setCap("既然解不唯一，就必须<b>外加一条准则</b>去挑一个。三种常见做法。");

clearScene();setBig(null);setEq(null);
lamps({y:280,gap:330,items:[
  {label:"解不唯一",sub:"R ≡ 0 就是一个",state:"dead"},
  {label:"必须加准则",sub:"间隔 / 熵 / 特征",state:"on"},
  {label:"准则即假设",sub:"它决定你恢复出什么",state:"on"}]});
note("这是建模选择，不是技术细节",640,420,"y");
setCap("<b>指名反驳</b>：行为定不出 R。<b>你选的准则，才决定了恢复出什么。</b>");
